const body = $json.body || $json;
const email = String(body.email || '').trim().toLowerCase();
const locale = body.locale === 'es' ? 'es' : 'en';
const dmg = body.dmg_url || 'https://stackdock.iareal.net/download/StackDock-4.0.4.dmg';
const sha = body.dmg_sha256 || '';
const team = body.team_id || 'YH6W55MP95';
const subjects = {
  en: [
    'Your StackDock 7-day trial starts now',
    'Summon docks on every display',
    'Split Chrome Work / Personal icons',
    'Teleport windows with Shift+Click',
    'Trial ends today — keep StackDock'
  ],
  es: [
    'Tu prueba de StackDock (7 días) ya empezó',
    'Invoca el Dock en cada pantalla',
    'Separa iconos de Chrome Trabajo / Personal',
    'Teletransporta ventanas con Shift+Clic',
    'La prueba termina hoy — quédate con StackDock'
  ]
};
const ctaPersonal = $env.STRIPE_CHECKOUT_URL_PERSONAL || 'https://stackdock.iareal.net/#pricing';
const ctaPro = $env.STRIPE_CHECKOUT_URL_PRO || 'https://stackdock.iareal.net/#pricing';
return [{
  json: {
    email,
    locale,
    dmg_url: dmg,
    dmg_sha256: sha,
    team_id: team,
    subject1: subjects[locale][0],
    subject2: subjects[locale][1],
    subject3: subjects[locale][2],
    subject4: subjects[locale][3],
    subject5: subjects[locale][4],
    cta_personal: ctaPersonal,
    cta_pro: ctaPro,
    html1: `<p>Download: <a href="${dmg}">${dmg}</a></p><p>SHA-256: <code>${sha}</code><br/>Apple Team ID: <code>${team}</code></p><p>Tip: press ⌥+D to summon StackDock on every display.</p>`
  }
}];
